class OrderManagementViewSet(viewsets.ViewSet):
    permission_classes = [permissions.IsAuthenticated]

    @action(detail=False, methods=['post'], url_path='cancel-orders')
    def cancel_orders(self, request):
        order_ids = request.data.get('order_ids', [])
        updated_count = Order.objects.filter(
            id__in=order_ids,
            customer=request.user
        ).update(status='cancelled')
        return Response({'cancelled': updated_count})
